// discouraged: model roles explicitly instead
enum Role { Borrower { limit: u64 }, Investor { amount: u64 } }
struct Customer { name: String, roles: Vec<Role> }
let limit = match &customer.roles[0] { Role::Borrower { limit } => *limit, _ => 0 };

// closest realizable analogue when dynamic extension is unavoidable:
struct Core { ext: HashMap<TypeId, Box<dyn Any + Send + Sync>> }
fn get<T: 'static + Send + Sync>(core: &Core) -> Option<&T> {
    core.ext.get(&TypeId::of::<T>())?.downcast_ref::<T>()
}
